let current = "en";
let dict = D.en;

export function setLanguage(code) {
  current = D[code] ? code : "en";
  dict = D[current];
  const meta = LANGUAGES.find((l) => l.code === current);
  document.documentElement.lang = current;
  document.documentElement.dir = meta?.rtl ? "rtl" : "ltr";
  return current;
}

export function language() {
  return current;
}

// Pick a supported language from the OS/browser preferences.
export function detectLanguage() {
  for (const tag of navigator.languages || [navigator.language || "en"]) {
    const base = String(tag).toLowerCase().split(/[-_]/)[0];
    if (D[base]) return base;
  }
  return "en";
}

export function t(key, vars) {
  let s = dict[key] ?? D.en[key] ?? key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] ?? m));
  return s;
}

export function has(key) {
  return key in dict || key in D.en;
}

// Backend messages are Turkish; map the known ones to translated keys.
const BACKEND = [
  [/yönetici izni verilmedi/i, "err.noAdmin"],
  [/^(\S+) adresi başka bir uygulama tarafından kullanılıyor/i, "err.portInUse", (m) => ({ addr: m[1] })],
  [/internet bağlantısı yok/i, "err.noInternet"],
  [/hiçbir DNS sunucusu yanıt vermedi/i, "err.noDNS"],
  [/tarama iptal edildi/i, "err.scanCancelled"],
  [/tarama zaten sürüyor/i, "err.scanRunning"],
  [/önce Otomatik Bypass taraması/i, "err.needScan"],
  [/güncelleme denetlenemedi/i, "err.updateCheck"],
  [/sahte paket kullanıyor ve yönetici/i, "err.root"],
];

export function translateBackend(msg) {
  if (!msg || current === "tr") return msg;
  for (const [re, key, vars] of BACKEND) {
    const m = String(msg).match(re);
    if (m) return t(key, vars ? vars(m) : undefined);
  }
  return msg;
}
